-- Domain 24: Community, Reviews & UGC | views
-- Generated by tools/split_by_domain.py. Statements keep their original order tag (@seq).

-- @seq 1540
CREATE VIEW public.ugc_post_stats_v WITH (security_invoker='true') AS
 SELECT id AS post_id,
    tenant_id,
    product_id,
    ( SELECT count(*) AS count
           FROM public.ugc_reactions r
          WHERE ((r.target_type = 'post'::text) AND (r.target_id = p.id))) AS like_count,
    ( SELECT count(*) AS count
           FROM public.ugc_comments c
          WHERE ((c.post_id = p.id) AND (c.status = 'published'::text))) AS comment_count
   FROM public.ugc_posts p;

